//! Cargo-driven `imm32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is imm32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/win32ss/user/imm32",
        "win32ss/user/imm32",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/wine",
        "win32ss/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["IMM_WIN3_SUPPORT", "UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_ImmDllInitialize@12", Some(0x79800000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "ImmDllInitialize", Some(0x7ff9a000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "ImmDllInitialize", Some(0x7ff9a000000u64)),
        o => panic!("imm32-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:c:win32ksys", "engine:uuid"],
        "x86_64" => &["engine:wine", "engine:c:win32ksys", "engine:uuid"],
        "aarch64" => &["engine:wine", "engine:c:win32ksys", "engine:uuid"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("imm32-rust")
        .rc("win32ss/user/imm32/imm32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("win32ss/user/imm32/imm32.spec", "imm32.dll")
        .spec_stubs()
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
